(42093, 'Joshua 9:1', 'Joshua', 9, 1, 'د اسراییلو د بریالیتوبونو څخه هغه ټول پاچاهان خبر شول چې د اردن د سیند په لوېدیځ کې وو، یعنې کوم چې په غرنۍ سیمه، د غرونو په لوېدیځو لمنو او د مدیترانې د بحیرې د غاړې څخه شمال خواته تر لبنان پورې اوسېدل. دا د حیتیانو، اموریانو، کنعانیانو، فرزیانو، حویانو او یبوسیانو پاچاهان وو.', 'د اسراییلو د بریالیتوبونو چخه هغه تول پاچاهان خبر شول چې د اردن د سیند په لوېدیج کې وو، یعنې کوم چې په غرنی سیمه، د غرونو په لوېدیجو لمنو او د مدیترانې د بحیرې د غارې چخه شمال خواته تر لبنان پورې اوسېدل. دا د حیتیانو، اموریانو، کنعانیانو، فرزیانو، حویانو او یبوسیانو پاچاهان وو.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42094, 'Joshua 9:2', 'Joshua', 9, 2, 'هغوی ټول سره راټول شول او د یوشع او اسراییلیانو په وړاندې د جنګ دپاره یې خپل قوتونه سره یو کړل.', 'هغوی تول سره راتول شول او د یوشع او اسراییلیانو په وراندې د جنګ دپاره یې خپل قوتونه سره یو کرل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42095, 'Joshua 9:3', 'Joshua', 9, 3, 'خو د جبعون خلکو چې حویان وو، واورېدل چې یوشع په اریحا او عای باندې څه کړي وو', 'خو د جبعون خلکو چې حویان وو، واورېدل چې یوشع په اریحا او عای باندې چه کری وو', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42096, 'Joshua 9:4', 'Joshua', 9, 4, 'او هغوی د یوشع د غولولو پرېکړه وکړه. هغوی لاړل او یو څه خواړه یې راواخیستل او په زړو بوجیو او ګنډل شویو د شرابو مشکونه یې په خپلو خرو بار کړل.', 'او هغوی د یوشع د غولولو پرېکره وکره. هغوی لارل او یو چه خواره یې راواخیستل او په زرو بوجیو او ګندل شویو د شرابو مشکونه یې په خپلو خرو بار کرل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42097, 'Joshua 9:5', 'Joshua', 9, 5, 'هغو خلکو زړې او ګنډل شوې څپلۍ او زاړه کالي واغوستل. کومه ډوډۍ چې هغوی د ځان سره اخیستې وه هغه وچه او چڼاسکو وهلې وه.', 'هغو خلکو زرې او ګندل شوې چپلی او زاره کالی واغوستل. کومه دودی چې هغوی د جان سره اخیستې وه هغه وچه او چناسکو وهلې وه.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42098, 'Joshua 9:6', 'Joshua', 9, 6, 'بیا هغوی یوشع ته هغه کمپ ته ورغلل چې په جلجال کې ؤ او هغه او اسراییلیانو ته یې وویل: «مونږ د یو لېرې هېواد څخه راغلي یو، ستاسو څخه غواړو چې زمونږ سره د سولې تړون وکړئ.»', 'بیا هغوی یوشع ته هغه کمپ ته ورغلل چې په جلجال کې و او هغه او اسراییلیانو ته یې وویل: «مونز د یو لېرې هېواد چخه راغلی یو، ستاسو چخه غوارو چې زمونز سره د سولې ترون وکری.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42099, 'Joshua 9:7', 'Joshua', 9, 7, 'خو اسراییلیانو وویل: «مونږ څنګه پوه شو چې تاسو زمونږ سره نژدې نه اوسېږئ؟ که چېرې نژدې اوسېږئ، نو بیا مونږ نه شو کولای چې ستاسو سره تړون وکړو.»', 'خو اسراییلیانو وویل: «مونز چنګه پوه شو چې تاسو زمونز سره نژدې نه اوسېزی؟ که چېرې نژدې اوسېزی، نو بیا مونز نه شو کولای چې ستاسو سره ترون وکرو.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42100, 'Joshua 9:8', 'Joshua', 9, 8, 'هغوی یوشع ته وویل: «مونږ ستا غلامان یو.» یوشع پوښتنه وکړه: «تاسو څوک یئ او د کوم ځای څخه راغلي یئ؟»', 'هغوی یوشع ته وویل: «مونز ستا غلامان یو.» یوشع پوشتنه وکره: «تاسو چوک یی او د کوم جای چخه راغلی یی؟»', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42101, 'Joshua 9:9', 'Joshua', 9, 9, 'هغوی په ځواب کې وویل: «ښاغلیه، مونږ د یو ډېر لېرې هېواد څخه راغلي یو، ځکه چې مونږ ستاسو د څښتن خدای د شهرت په اړه اورېدلي دي. مونږ د هغو ټولو کارونو څخه خبر یو چې هغه په مصر کې کړي دي', 'هغوی په جواب کې وویل: «شاغلیه، مونز د یو دېر لېرې هېواد چخه راغلی یو، جکه چې مونز ستاسو د چشتن خدای د شهرت په اره اورېدلی دی. مونز د هغو تولو کارونو چخه خبر یو چې هغه په مصر کې کری دی', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42102, 'Joshua 9:10', 'Joshua', 9, 10, 'او هرڅه چې هغه د اردن د سیند په ختیځ کې د اموریانو په دوو پاچاهانو باندې وکړل یعنې د حشبون په پاچا سیحون او د باشان په پاچا عوج چې په عشتاروت کې اوسېده.', 'او هرچه چې هغه د اردن د سیند په ختیج کې د اموریانو په دوو پاچاهانو باندې وکرل یعنې د حشبون په پاچا سیحون او د باشان په پاچا عوج چې په عشتاروت کې اوسېده.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42103, 'Joshua 9:11', 'Joshua', 9, 11, 'زمونږ مشرانو او هغو ټولو خلکو چې زمونږ په هېواد کې اوسیږي مونږ ته وویل چې د خپل سفر دپاره له ځان سره د خوړلو او څښلو دپاره یو څه یوسو، لاړ شو د اسراییلیانو سره ووینو او ورته ووایو چې مونږ ستاسو غلامان یو، زمونږ سره یو تړون وکړئ.', 'زمونز مشرانو او هغو تولو خلکو چې زمونز په هېواد کې اوسیزی مونز ته وویل چې د خپل سفر دپاره له جان سره د خورلو او چشلو دپاره یو چه یوسو، لار شو د اسراییلیانو سره ووینو او ورته ووایو چې مونز ستاسو غلامان یو، زمونز سره یو ترون وکری.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42104, 'Joshua 9:12', 'Joshua', 9, 12, 'زمونږ ډوډۍ ته وګورئ. کله چې مونږ د کور څخه راروان شو هغه توده وه. خو اوس وګورئ! هغه وچه شوې او چڼاسکو وهلې ده.', 'زمونز دودی ته وګوری. کله چې مونز د کور چخه راروان شو هغه توده وه. خو اوس وګوری! هغه وچه شوې او چناسکو وهلې ده.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42105, 'Joshua 9:13', 'Joshua', 9, 13, 'کله چې مونږ د شرابو دا مشکونه ډک کړل، هغه نوي وو. خو وګورئ! هغه شلېدلي دي. د دې اوږد سفر له امله زمونږ کالي او څپلۍ زړې شوې دي.»', 'کله چې مونز د شرابو دا مشکونه دک کرل، هغه نوی وو. خو وګوری! هغه شلېدلی دی. د دې اوزد سفر له امله زمونز کالی او چپلی زرې شوې دی.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42106, 'Joshua 9:14', 'Joshua', 9, 14, 'اسراییلیانو د هغوی یو څه ډوډۍ قبوله کړه، خو په دې هکله یې د څښتن سره مشوره ونه کړه.', 'اسراییلیانو د هغوی یو چه دودی قبوله کره، خو په دې هکله یې د چشتن سره مشوره ونه کره.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42107, 'Joshua 9:15', 'Joshua', 9, 15, 'یوشع د جبعون د خلکو سره د دوستۍ تړون وکړ او هغوی یې ژوندي پرېښودل. د اسراییلو مشرانو قسم وخوړ چې په دې تړون باندې به عمل کوي.', 'یوشع د جبعون د خلکو سره د دوستی ترون وکر او هغوی یې ژوندی پرېشودل. د اسراییلو مشرانو قسم وخور چې په دې ترون باندې به عمل کوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42108, 'Joshua 9:16', 'Joshua', 9, 16, 'د جبعونیانو سره د تړون د کولو څخه درې ورځې وروسته اسراییلیانو واورېدل چې دا ګاونډیان دي او د هغوی سره نژدې اوسیږي.', 'د جبعونیانو سره د ترون د کولو چخه درې ورجې وروسته اسراییلیانو واورېدل چې دا ګاوندیان دی او د هغوی سره نژدې اوسیزی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42109, 'Joshua 9:17', 'Joshua', 9, 17, 'نو اسراییلیان روان شول او په درېمه ورځ هغو ښارونو ته ورسېدل چې دا خلک په کې اوسېدل یعنې جبعون، کفیره، بیروت او قریت یعاریم ته.', 'نو اسراییلیان روان شول او په درېمه ورج هغو شارونو ته ورسېدل چې دا خلک په کې اوسېدل یعنې جبعون، کفیره، بیروت او قریت یعاریم ته.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42110, 'Joshua 9:18', 'Joshua', 9, 18, 'خو اسراییلیانو نه شو کولای چې هغوی ووژني، ځکه چې د هغوی مشرانو د جبعونیانو سره د اسراییلو د څښتن خدای په نوم قسم خوړلی ؤ. ټول قوم د مشرانو څخه ګیله وکړه،', 'خو اسراییلیانو نه شو کولای چې هغوی ووژنی، جکه چې د هغوی مشرانو د جبعونیانو سره د اسراییلو د چشتن خدای په نوم قسم خورلی و. تول قوم د مشرانو چخه ګیله وکره،', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42111, 'Joshua 9:19', 'Joshua', 9, 19, 'خو هغوی په ځواب کې وویل: «مونږ د هغوی سره د اسراییلو د څښتن خدای په نوم قسم خوړلی دی. اوس هغوی ته زیان نه شو رسولی.', 'خو هغوی په جواب کې وویل: «مونز د هغوی سره د اسراییلو د چشتن خدای په نوم قسم خورلی دی. اوس هغوی ته زیان نه شو رسولی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42112, 'Joshua 9:20', 'Joshua', 9, 20, 'مونږ باید د خپلې وعدې په خاطر هغوی ژوندي پرېږدو. که داسې ونه کړو، نو خدای به مونږ ته سزا راکړي.', 'مونز باید د خپلې وعدې په خاطر هغوی ژوندی پرېزدو. که داسې ونه کرو، نو خدای به مونز ته سزا راکری.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42113, 'Joshua 9:21', 'Joshua', 9, 21, 'هغوی ژوندي پرېږدئ، خو هغوی باید زمونږ دپاره لرګي مات کړي او اوبه راوړي.» دا د مشرانو وړاندیز ؤ.', 'هغوی ژوندی پرېزدی، خو هغوی باید زمونز دپاره لرګی مات کری او اوبه راوری.» دا د مشرانو وراندیز و.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42114, 'Joshua 9:22', 'Joshua', 9, 22, 'بیا یوشع د جبعون خلک راوغوښتل او هغوی ته یې وویل: «تاسو ولې مونږ وغولولو او داسې مو وویل چې مونږ د لېرې ځای څخه یو، حال دا چې زمونږ سره نژدې اوسېږئ؟', 'بیا یوشع د جبعون خلک راوغوشتل او هغوی ته یې وویل: «تاسو ولې مونز وغولولو او داسې مو وویل چې مونز د لېرې جای چخه یو، حال دا چې زمونز سره نژدې اوسېزی؟', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42115, 'Joshua 9:23', 'Joshua', 9, 23, 'په دې خاطر چې تاسو داسې کار وکړ، نو اوس په تاسو باندې لعنت ویل شوی دی. ستاسو خلک به تل ترتله غلامان وي او زما د خدای کور ته به لرګي ماتوي او اوبه به راوړي.»', 'په دې خاطر چې تاسو داسې کار وکر، نو اوس په تاسو باندې لعنت ویل شوی دی. ستاسو خلک به تل ترتله غلامان وی او زما د خدای کور ته به لرګی ماتوی او اوبه به راوری.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42116, 'Joshua 9:24', 'Joshua', 9, 24, 'هغوی په ځواب کې وویل: «ښاغلیه، مونږ خبر شو چې دا رښتیا وه چې ستا څښتن خدای خپل خدمتګار موسی ته حکم کړی ؤ چې تاته به دا ټوله ځمکه درکړي او کوم خلک چې په کې اوسیږي هغوی به ستا له مخې څخه ورک کړي. نو مونږ ځکه داسې کار وکړ چې ستاسو څخه سخت وېرېدلو چې مونږ به ووژنئ.', 'هغوی په جواب کې وویل: «شاغلیه، مونز خبر شو چې دا رشتیا وه چې ستا چشتن خدای خپل خدمتګار موسی ته حکم کری و چې تاته به دا توله جمکه درکری او کوم خلک چې په کې اوسیزی هغوی به ستا له مخې چخه ورک کری. نو مونز جکه داسې کار وکر چې ستاسو چخه سخت وېرېدلو چې مونز به ووژنی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42117, 'Joshua 9:25', 'Joshua', 9, 25, 'اوس مونږ ستا په لاس کې یو. هرڅه چې تاته ښه او مناسب ښکاري زمونږ سره یې وکړه.»', 'اوس مونز ستا په لاس کې یو. هرچه چې تاته شه او مناسب شکاری زمونز سره یې وکره.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42118, 'Joshua 9:26', 'Joshua', 9, 26, 'نو یوشع هغوی د اسراییلیانو څخه وژغورل او هغوی جبعونیان ونه وژل.', 'نو یوشع هغوی د اسراییلیانو چخه وژغورل او هغوی جبعونیان ونه وژل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42119, 'Joshua 9:27', 'Joshua', 9, 27, 'خو په هماغه ورځ یوشع هغوی غلامان کړل چې د اسراییلو خلکو او د څښتن د قربانۍ ځای دپاره لرګي مات کړي او اوبه ورته راوړي. تر نن ورځې پورې هغوی په هغه ځای کې چې څښتن د خپل عبادت دپاره غوره کړی دی همدا کار کوي.', 'خو په هماغه ورج یوشع هغوی غلامان کرل چې د اسراییلو خلکو او د چشتن د قربانی جای دپاره لرګی مات کری او اوبه ورته راوری. تر نن ورجې پورې هغوی په هغه جای کې چې چشتن د خپل عبادت دپاره غوره کری دی همدا کار کوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237841, 1761237841),
(42120, 'Psalms 57:1', 'Psalms', 57, 1, 'په ما رحم وکړه خدایه، رحم وکړه ځکه چې تاته مې پناه راوړې پناه به زه ستا د وزرو تر سیوري لاندې واخلم ترڅو تېر دغه افت شي', 'په ما رحم وکره خدایه، رحم وکره جکه چې تاته مې پناه راورې پناه به زه ستا د وزرو تر سیوری لاندې واخلم ترچو تېر دغه افت شی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42121, 'Psalms 57:2', 'Psalms', 57, 2, 'زه کومه خدای تعالی ته فریاد هغه خدای ته چې خپل مقصد زما دپاره سر ته رسوي', 'زه کومه خدای تعالی ته فریاد هغه خدای ته چې خپل مقصد زما دپاره سر ته رسوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42122, 'Psalms 57:3', 'Psalms', 57, 3, 'کړي له اسمانه به قبوله مې دعا نجات به راکړي ماته هغه چې ما باندې کړي ظلم خدای به ورکړي شرم خدای به راوښایي وفا او هم تلپاتې مینه', 'کری له اسمانه به قبوله مې دعا نجات به راکری ماته هغه چې ما باندې کری ظلم خدای به ورکری شرم خدای به راوشایی وفا او هم تلپاتې مینه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42123, 'Psalms 57:4', 'Psalms', 57, 4, 'زه د داسې دښمنانو له خوا ګېر یم چې د زمرو په شان دي وږي د انسان غوښو ته د دوی غاښونه دي د غشو او نېزو په شان د هغوی ژبې دي تېرې لکه د تورو په شان', 'زه د داسې دشمنانو له خوا ګېر یم چې د زمرو په شان دی وزی د انسان غوشو ته د دوی غاشونه دی د غشو او نېزو په شان د هغوی ژبې دی تېرې لکه د تورو په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42124, 'Psalms 57:5', 'Psalms', 57, 5, 'خدایه لویي دې کړه ظاهره اسمانونو باندې په ټوله ځمکه خپل جلال ښکاره کړه', 'خدایه لویی دې کره ظاهره اسمانونو باندې په توله جمکه خپل جلال شکاره کره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42125, 'Psalms 57:6', 'Psalms', 57, 6, 'دی دښمنانو راته ایښی دام چې ګېر مې کړي له پرېشانۍ نه ستړی شوی یمه کنده کیندلې وه هغوی راته په لاره کې خو دوی په خپله په کې ولوېدل', 'دی دشمنانو راته ایشی دام چې ګېر مې کری له پرېشانی نه ستری شوی یمه کنده کیندلې وه هغوی راته په لاره کې خو دوی په خپله په کې ولوېدل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42126, 'Psalms 57:7', 'Psalms', 57, 7, 'زه په تا باندې ډاډه یمه ای خدایه زه ډاډه یم زه به وایمه سندرې ستا صفت به کوم', 'زه په تا باندې داده یمه ای خدایه زه داده یم زه به وایمه سندرې ستا صفت به کوم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(42127, 'Psalms 57:8', 'Psalms', 57, 8, 'شه راویښ زما ځانه! ای زما چنګه او ربابه رابېدار شئ! زه راویښ به سباوون کړم', 'شه راویش زما جانه! ای زما چنګه او ربابه رابېدار شی! زه راویش به سباوون کرم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_57_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
